add("ex2i", ("लौह और अलौह खनिजों में अंतर स्पष्ट करें। उदाहरण भी दें।", "લોહ અને અલોહ ખનિજો વચ્ચે તફાવત સ્પષ્ટ કરો. ઉદાહરણો પણ આપો."),
    {0: ("लौह खनिजों में लोहा होता है, जैसे लौह अयस्क और मैंगनीज़; ये धात्विक खनिजों के उत्पादन मूल्य का लगभग तीन-चौथाई हैं।", "લોહ ખનિજોમાં લોખંડ હોય છે, જેમ કે લોખંડની ખનિજ અને મૅંગેનીઝ; તે ધાત્વિક ખનિજોના ઉત્પાદન મૂલ્યનો આશરે ત્રણ-ચતુર્થાંશ ભાગ છે."),
     1: ("अलौह खनिजों में लोहा नहीं होता, जैसे ताँबा, बॉक्साइट, सीसा, जस्ता और सोना।", "અલોહ ખનિજોમાં લોખંડ હોતું નથી, જેમ કે તાંબું, બૉક્સાઇટ, સીસું, જસત અને સોનું."),
     2: ("भारत लौह खनिजों में समृद्ध है, पर अलौह खनिजों के भंडार और उत्पादन बहुत संतोषजनक नहीं हैं।", "ભારત લોહ ખનિજોમાં સમૃદ્ધ છે, પણ અલોહ ખનિજોના ભંડાર અને ઉત્પાદન બહુ સંતોષકારક નથી.")})
add("ex2ii", ("ऊर्जा के परंपरागत और ग़ैर-परंपरागत साधनों में अंतर कीजिए।", "ઊર્જાના પરંપરાગત અને બિનપરંપરાગત સ્રોતો વચ્ચે તફાવત કરો."),
    {0: ("परंपरागत साधन लंबे समय से प्रयुक्त हैं: लकड़ी, उपले, कोयला, पेट्रोलियम, प्राकृतिक गैस और विद्युत (जल और ताप)।", "પરંપરાગત સ્રોતો લાંબા સમયથી વપરાય છે: લાકડાં, છાણાં, કોલસો, પેટ્રોલિયમ, કુદરતી વાયુ અને વીજળી (જળ અને તાપ)."),
     1: ("ग़ैर-परंपरागत साधन नए हैं: सौर, पवन, ज्वारीय, भूतापीय, बायोगैस और परमाणु ऊर्जा।", "બિનપરંપરાગત સ્રોતો નવા છે: સૌર, પવન, ભરતી, ભૂતાપીય, બાયોગૅસ અને પરમાણુ ઊર્જા."),
     2: ("अधिकांश परंपरागत साधन (जीवाश्म ईंधन) अनवीकरण योग्य और प्रदूषणकारी हैं; अधिकांश ग़ैर-परंपरागत साधन नवीकरण योग्य और स्वच्छ हैं।", "મોટા ભાગના પરંપરાગત સ્રોતો (અશ્મિ ઇંધણો) અપુનઃપ્રાપ્ય અને પ્રદૂષણકારી છે; મોટા ભાગના બિનપરંપરાગત સ્રોતો પુનઃપ્રાપ્ય અને સ્વચ્છ છે.")})
add("ex3i", ("हमें खनिजों का संरक्षण क्यों करना चाहिए?", "આપણે ખનિજોનું સંરક્ષણ કેમ કરવું જોઈએ?"),
    {0: ("कार्य योग्य खनिज निक्षेप भू-पर्पटी का नगण्य भाग (एक प्रतिशत) हैं।", "ખોદી શકાય તેવા ખનિજ નિક્ષેપો પૃથ્વીના પોપડાનો નજીવો ભાગ (એક ટકો) છે."),
     1: ("खनिज बनने की भूगर्भिक प्रक्रियाएँ इतनी धीमी हैं कि पुनर्भरण की दर उपभोग की तुलना में अनंत गुना कम है।", "ખનિજ બનવાની ભૂસ્તરીય પ્રક્રિયાઓ એટલી ધીમી છે કે ફરી ભરાવાનો દર ઉપભોગની સરખામણીમાં અતિ નજીવો છે."),
     2: ("खनिज सीमित और अनवीकरण योग्य हैं; समृद्ध निक्षेप तेज़ी से ख़त्म हो रहे हैं।", "ખનિજો મર્યાદિત અને અપુનઃપ્રાપ્ય છે; સમૃદ્ધ નિક્ષેપો ઝડપથી ખૂટી રહ્યા છે."),
     3: ("लगातार निष्कर्षण से लागत बढ़ती है क्योंकि खनिज अधिक गहराई से और कम गुणवत्ता के साथ निकलते हैं।", "સતત ખોદકામથી ખર્ચ વધે છે કારણ કે ખનિજો વધુ ઊંડાઈએથી અને ઓછી ગુણવત્તા સાથે નીકળે છે."),
     4: ("इसलिए हमें खनिजों का सुनियोजित और सतत उपयोग, निम्न कोटि के अयस्कों के लिए प्रौद्योगिकी, और धातुओं का पुनःचक्रण तथा रद्दी और प्रतिस्थापनों का उपयोग करना चाहिए।", "તેથી આપણે ખનિજોનો આયોજિત અને ટકાઉ ઉપયોગ, નીચી ગુણવત્તાની ઓર માટે ટેકનોલોજી, અને ધાતુઓનું પુનઃચક્રણ તથા ભંગાર અને વિકલ્પોનો ઉપયોગ કરવો જોઈએ.")})
add("ex3ii", ("भारत में ग़ैर-परंपरागत ऊर्जा संसाधनों के वितरण का वर्णन कीजिए।", "ભારતમાં બિનપરંપરાગત ઊર્જા સંસાધનોના વિતરણનું વર્ણન કરો."),
    {0: ("परमाणु: झारखंड और राजस्थान की अरावली में यूरेनियम और थोरियम; केरल की मोनाज़ाइट रेत में थोरियम; नरोरा, काकरापार, तारापुर और कलपक्कम में संयंत्र।", "પરમાણુ: ઝારખંડ અને રાજસ્થાનની અરવલ્લીમાં યુરેનિયમ અને થોરિયમ; કેરલની મોનાઝાઇટ રેતીમાં થોરિયમ; નરોરા, કાકરાપાર, તારાપુર અને કલ્પક્કમમાં મથકો."),
     1: ("सौर: भारत उष्ण कटिबंधीय है; भुज (माधापुर) के पास एक बड़ा सौर संयंत्र दूध के बर्तनों को कीटाणुमुक्त करता है।", "સૌર: ભારત ઉષ્ણ કટિબંધીય છે; ભુજ (માધાપર) પાસે એક મોટો સૌર પ્લાન્ટ દૂધના કૅન જંતુમુક્ત કરે છે."),
     2: ("पवन: सबसे बड़ा समूह तमिलनाडु में नागरकोइल से मदुरै तक; आंध्र प्रदेश, कर्नाटक, गुजरात, केरल, महाराष्ट्र और लक्षद्वीप भी; जैसलमेर प्रसिद्ध है।", "પવન: સૌથી મોટું સમૂહ તમિળનાડુમાં નાગરકોઇલથી મદુરાઈ સુધી; આંધ્ર પ્રદેશ, કર્ણાટક, ગુજરાત, કેરલ, મહારાષ્ટ્ર અને લક્ષદ્વીપ પણ; જેસલમેર જાણીતું છે."),
     3: ("बायोगैस: ग्रामीण क्षेत्रों में नगरपालिका, सहकारी और व्यक्तिगत स्तर पर गोबर गैस संयंत्र।", "બાયોગૅસ: ગ્રામીણ વિસ્તારોમાં નગરપાલિકા, સહકારી અને વ્યક્તિગત સ્તરે ગોબર ગૅસ પ્લાન્ટ."),
     4: ("ज्वारीय: खंभात और कच्छ की खाड़ियाँ (गुजरात) और सुंदरबन डेल्टा (पश्चिम बंगाल); भूतापीय: पार्वती घाटी (हिमाचल प्रदेश) और पूगा घाटी (लद्दाख)।", "ભરતી: ખંભાત અને કચ્છના અખાત (ગુજરાત) અને સુંદરવન મુખત્રિકોણ (પશ્ચિમ બંગાળ); ભૂતાપીય: પાર્વતી ખીણ (હિમાચલ પ્રદેશ) અને પુગા ખીણ (લદ્દાખ).")})

